 const frame=(o,t)=>{const c=Math.cos(o.a),s=Math.sin(o.a);const dx=t.cx-o.cx,dy=t.cy-o.cy;return{u:dx*c-dy*s,v:dx*s+dy*c}};// u: yazı yönünde ileri, v: aşağı\n  items.forEach((n,i)=>{if(used.has(i)||(skip&&skip.has(n))||!NOM.test(n.s))return;const h=n.h||8;const right=n.w/2;\n    const cand=items.map((t,j)=>({t,j,...frame(n,t)})).filter(x=>x.j!==i&&!used.has(x.j)&&!(skip&&skip.has(x.t))&&Math.abs((x.t.a||0)-(n.a||0))<0.05&&x.u>right-h*0.3&&x.u-x.t.w/2<right+h*1.6);\n    const up=cand.filter(x=>TOL.test(x.t.s)&&x.v<-h*0.12&&x.v>-h*1.3).sort((a,b)=>a.u-b.u)[0],lo=cand.filter(x=>TOL.test(x.t.s)&&x.v>h*0.12&&x.v<h*1.3).sort((a,b)=>a.u-b.u)[0];\n    let s=null,parts=[];\n    if(up&&lo){const f=v=>v.replace(/−/g,'-').replace(/\\s+/g,'');const a=f(up.t.s),b=f(lo.t.s);s=`${n.s} ${a==='0'?'0':(/^[+-]/.test(a)?a:'+'+a)}/${b==='0'?'0':(/^[+-]/.test(b)?b:'-'+b)}`;parts=[up,lo]}\n    else{const same=cand.filter(x=>Math.abs(x.v)<h*0.45).sort((a,b)=>a.u-b.u)[0];if(same&&(PM.test(same.t.s)||FIT.test(same.t.s))){s=`${n.s} ${same.t.s.replace(/\\s+/g,'')}`;parts=[same]}}\n    if(s){used.add(i);parts.forEach(p=>used.add(p.j));let l=-n.w/2,r=n.w/2;parts.forEach(p=>{r=Math.max(r,p.u+p.t.w/2)});const mid=(l+r)/2;const c=Math.cos(n.a),sn=Math.sin(n.a);\n      out.push({...n,s,w:r-l,cx:n.cx+mid*c,cy:n.cy-mid*sn,merged:true})}});\n  return items.filter((_,i)=>!used.has(i)).concat(out);\n}\n\n/* ---- muayene resmi arayüzü ---- */\nlet DGLAST=null;\nfunction dgStripBalloons(svg){const i=svg.indexOf('<g id=\"dg-balloons\">');if(i<0)return svg;let depth=0,j=i;const re=/<\\/?g\\b[^>]*>/g;re.lastIndex=i;let m;while((m=re.exec(svg))){if(m[0].startsWith('</'))depth--;else depth++;if(depth===0){j=m.index+m[0].length;break}}return svg.slice(0,i)+svg.slice(j)}\nasync function svgToCanvas(svg,pxPerMM){\n  const W=420,H=297;const blob=new Blob([svg],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);\n  const img=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=url});\n  const cv=document.createElement('canvas');cv.width=Math.round(W*pxPerMM);cv.height=Math.round(H*pxPerMM);const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(url);return cv;\n}\nfunction genDrawingDialog(){\n  if(!M3.meshes||!M3.meshes.length)return toast('Muayene resmi için 3D model görüntüsünün yüklenmiş olması gerekir.','bad');\n  const F=[{k:'hidden',label:'Gizli çizgiler',type:'bool',boolLabel:'Kesikli çizgiyle göster',def:true},{k:'balon',label:'Balonlar',type:'bool',boolLabel:`${ED.doc.balonlar.length} balonu resme ekle`,def:true},{k:'annot',label:'Tolerans ve datum gösterimi',type:'select',options:[['tbl','Karakteristik tablosu: balonlar görünüş çevresinde sıralı (önerilen)'],['lbl','Her balonun yanında tolerans yazısı'],['pres','Tablo ve CAD\\'in modele işlediği PMI çizimleri'],['none','Yalnız balonlar']],w:'f'},{k:'hazirlayan',label:'Hazırlayan',def:ME.dolduran||''}];\n  formModal('STEP\\'ten muayene resmi',F,null,async x=>{closeModal(true);toast('Muayene resmi hazırlanıyor…');await sleep(40);\n    try{const d=ED.doc;const out=genInspectionDrawing(M3.meshes,{stepM:ED.stepM,pmi:ED.pmi,pres:ED.pmi&&ED.pmi.pres,annot:x.annot||'tbl',balloons:x.balon?d.balonlar.filter(gfPass).map(b=>({...b,_k:kanalOf(b)})):[],unit:d.birim||'mm',hidden:x.hidden,firma:G().firma||'',parcaNo:d.parcaNo,parcaAdi:d.parcaAdi||'',rev:d.rev||'',hazirlayan:x.hazirlayan,kaynak:(d.dosyaAdi||'STEP').slice(0,28)});window.DGLAST=out;\n      DGLAST={out,doc:d};dgPreview()}catch(err){console.error(err);toast('Resim oluşturulamadı: '+(err&&err.message||'hata'),'bad')}},\n    `<p class=\"muted\" style=\"font-size:13px;margin-top:10px\">A3 yatay pafta; ISO birinci açı yerleşimi (ön, üst, sol görünüş ve izometrik). Genel ölçüler ve delikler STEP geometrisinden ölçülür. Pafta \"imalat resmi değildir\" ibaresi taşır.</p>`);\n}\nfunction dgPreview(){\n  const {out,doc}=DGLAST;const ok